use super::*;

// Go: TestRenderParseOps.
#[test]
fn render_parse_ops() {
    let ops = vec![
        Op::moved("aws_s3_bucket.old", "aws_s3_bucket.new"),
        Op::import(r#"module.d.aws_s3_bucket.x["k"]"#, "the-bucket"),
        Op::removed("module.s.aws_s3_bucket.x"),
    ];
    let content = render_shim("PR-123", &ops);
    assert_eq!(
        content,
        "# Generated by `tfstackplan state move` — do not edit by hand.\n\
# tfstackplan:key=PR-123\n\
# tfstackplan:op=moved\taws_s3_bucket.old\taws_s3_bucket.new\t\n\
# tfstackplan:op=import\t\tmodule.d.aws_s3_bucket.x[\"k\"]\tthe-bucket\n\
# tfstackplan:op=removed\tmodule.s.aws_s3_bucket.x\t\t\n\
\nmoved {\n  from = aws_s3_bucket.old\n  to   = aws_s3_bucket.new\n}\n\
\nimport {\n  to = module.d.aws_s3_bucket.x[\"k\"]\n  id = \"the-bucket\"\n}\n\
\nremoved {\n  from = module.s.aws_s3_bucket.x\n  lifecycle {\n    destroy = false\n  }\n}\n"
    );
    let (key, got) = parse_shim(&content).unwrap();
    assert_eq!(key, "PR-123");
    assert_eq!(got, ops);
}

// Go: TestParseShimRejectsForeign.
#[test]
fn parse_shim_rejects_foreign() {
    assert_eq!(
        parse_shim("resource \"x\" \"y\" {}\n").unwrap_err(),
        "not a tfstackplan state-move shim"
    );
}

// Go: TestMergeOpsDedup.
#[test]
fn merge_ops_dedup() {
    let a = vec![Op::moved("x.a", "x.b")];
    let b = vec![Op::moved("x.a", "x.b"), Op::removed("y.a")];
    assert_eq!(merge_ops(&a, &b).len(), 2);
}

// Go: TestShimFileName.
#[test]
fn shim_file_names() {
    assert_eq!(shim_file_name("PR-123"), "_tfsp_move.PR-123.tf");
    assert_eq!(shim_key_from_file("_tfsp_move.PR-1.tf"), Some("PR-1"));
    assert_eq!(shim_key_from_file("main.tf"), None);
    assert_eq!(shim_key_from_file("_tfsp_move.tf"), None);
}

#[test]
fn parse_shim_errors() {
    let banner = "# Generated by `tfstackplan state move` — do not edit by hand.\n";
    assert_eq!(parse_shim(banner).unwrap_err(), "shim missing key header");
    assert_eq!(
        parse_shim(&format!(
            "{banner}# tfstackplan:key=k\n# tfstackplan:op=moved\ta\n"
        ))
        .unwrap_err(),
        "malformed op line: \"# tfstackplan:op=moved\\ta\""
    );
}
